// =============================================================================
// Canonical player attribute schema
// =============================================================================
// Single source of truth for player attributes. Every player — master veterans
// from `players.js`, rookies generated by `CampaignManager.generateAttributes`,
// and randomly-generated team fillers — MUST end up with exactly these keys
// inside `attributes.{offense,defense,physical,mental}`.
//
// Why this file exists:
// Older code generated rookies with both legacy short-form keys (`dunk`,
// `passing`, `perimeterD`, `defensiveIQ`, `consistency`) AND canonical keys.
// Master players only ever had canonical keys. The scouting UI iterates the
// keys present on the player object and reveals attributes by canonical name —
// so legacy duplicates would never reveal, leaving '?' visible even at 100%
// scouted. By forcing every code path through this schema we eliminate the
// drift.

export const CANONICAL_ATTRIBUTES = {
  offense: [
    'closeShot',
    'midRange',
    'threePoint',
    'freeThrow',
    'shotIQ',
    'offensiveConsistency',
    'layup',
    'standingDunk',
    'drivingDunk',
    'postHook',
    'postFade',
    'postControl',
    'drawFoul',
    'hands',
    'ballHandling',
    'speedWithBall',
    'passAccuracy',
    'passVision',
    'passIQ',
  ],
  defense: [
    'interiorDefense',
    'perimeterDefense',
    'steal',
    'block',
    'offensiveRebound',
    'defensiveRebound',
    'helpDefenseIQ',
    'passPerception',
    'defensiveConsistency',
  ],
  physical: [
    'speed',
    'acceleration',
    'strength',
    'vertical',
    'stamina',
    'hustle',
    'durability',
  ],
  mental: [
    'basketballIQ',
    'clutch',
    'workEthic',
    'coachability',
    'intangibles',
  ],
}

// Flat list of canonical attribute keys — handy for iterating without nesting.
export const CANONICAL_ATTRIBUTE_LIST = [
  ...CANONICAL_ATTRIBUTES.offense,
  ...CANONICAL_ATTRIBUTES.defense,
  ...CANONICAL_ATTRIBUTES.physical,
  ...CANONICAL_ATTRIBUTES.mental,
]

// Including the two top-level rating fields the scouting UI also tracks. Used
// by ScoutingView / DraftRoomView for "X attributes revealed of Y total".
export const SCOUTABLE_ATTRIBUTES = ['overallRating', 'potentialRating', ...CANONICAL_ATTRIBUTE_LIST]

// Display groupings used by ScoutingView — same shape as CANONICAL_ATTRIBUTES
// but keyed by user-facing labels and prefixed with the Ratings group.
export const SCOUTABLE_ATTRIBUTE_CATEGORIES = {
  Ratings: ['overallRating', 'potentialRating'],
  Offense: CANONICAL_ATTRIBUTES.offense,
  Defense: CANONICAL_ATTRIBUTES.defense,
  Physical: CANONICAL_ATTRIBUTES.physical,
  Mental: CANONICAL_ATTRIBUTES.mental,
}

// Maps a legacy short-form key to its canonical replacement. Used by
// `normalizePlayerAttributes` to migrate older saves on read.
//   - `dunk` is a single legacy key; we project it onto BOTH standingDunk and
//     drivingDunk so the migrated player still feels right around the rim.
//   - `passing` similarly fans out into the three pass canonical keys.
//   - `postScoring` fans out into the three post canonical keys.
const LEGACY_TO_CANONICAL = {
  // offense
  postScoring: ['postHook', 'postFade', 'postControl'],
  dunk: ['standingDunk', 'drivingDunk'],
  passing: ['passAccuracy', 'passVision', 'passIQ'],
  // defense
  perimeterD: ['perimeterDefense'],
  interiorD: ['interiorDefense'],
  defensiveIQ: ['helpDefenseIQ'],
  // mental — `consistency` (singular) was generated in a previous version of
  // `generateMentalAttributes`. Project it onto BOTH offensive and defensive
  // consistency so neither side starts at zero.
  consistency: ['offensiveConsistency', 'defensiveConsistency'],
}

// Mapping of a legacy key to the category it belonged in, so we know where to
// fan it out within `attributes.{category}`.
const LEGACY_KEY_CATEGORY = {
  postScoring: 'offense',
  dunk: 'offense',
  passing: 'offense',
  perimeterD: 'defense',
  interiorD: 'defense',
  defensiveIQ: 'defense',
  consistency: ['offense', 'defense'], // consistency fans across both
}

/**
 * Ensure a player's `attributes` object exactly matches the canonical schema.
 * Mutates the player in place AND returns it (so callers can chain).
 *
 * - Migrates legacy keys to their canonical equivalents (legacy values used
 *   as the seed for the new canonical key when the canonical key is missing).
 * - Fills any missing canonical keys with the player's overallRating (clamped
 *   40–99) so we never leave a key undefined.
 * - Strips any keys not in the canonical schema.
 *
 * Safe to call multiple times — already-canonical players are unchanged.
 */
export function normalizePlayerAttributes(player) {
  if (!player || typeof player !== 'object') return player
  if (!player.attributes || typeof player.attributes !== 'object') {
    player.attributes = { offense: {}, defense: {}, physical: {}, mental: {} }
  }

  const fallback = clamp40to99(player.overallRating ?? player.overall_rating ?? 70)

  for (const category of ['offense', 'defense', 'physical', 'mental']) {
    const current = player.attributes[category] ?? {}
    const canonicalKeys = CANONICAL_ATTRIBUTES[category]

    // Step 1: migrate legacy keys into canonical equivalents (without
    // overwriting an existing canonical value — preserve the canonical when
    // both exist).
    for (const [legacyKey, targets] of Object.entries(LEGACY_TO_CANONICAL)) {
      if (current[legacyKey] === undefined) continue
      const cat = LEGACY_KEY_CATEGORY[legacyKey]
      const isInThisCategory = Array.isArray(cat) ? cat.includes(category) : cat === category
      if (!isInThisCategory) continue
      for (const target of targets) {
        if (canonicalKeys.includes(target) && current[target] === undefined) {
          current[target] = current[legacyKey]
        }
      }
    }

    // Step 2: fill missing canonical keys with the fallback.
    for (const key of canonicalKeys) {
      if (current[key] === undefined || current[key] === null) {
        current[key] = fallback
      }
    }

    // Step 3: strip any non-canonical keys (legacy or otherwise).
    const cleaned = {}
    for (const key of canonicalKeys) cleaned[key] = current[key]
    player.attributes[category] = cleaned
  }

  return player
}

function clamp40to99(value) {
  const n = Number(value)
  if (!Number.isFinite(n)) return 70
  return Math.max(40, Math.min(99, Math.round(n)))
}
